// Java record fixture — exercises java.lang.runtime.ObjectMethods.bootstrap
// for the synthetic equals/hashCode/toString methods generated by javac.
// Compile: javac --release 21 BenchRecord.java
public class BenchRecord {
    public record Point(int x, int y) {}

    public static int eqSame() {
        Point a = new Point(3, 5);
        Point b = new Point(3, 5);
        return a.equals(b) ? 1 : 0;
    }

    public static int eqDiff() {
        Point a = new Point(3, 5);
        Point b = new Point(3, 6);
        return a.equals(b) ? 1 : 0;
    }

    public static int hashCodeOk() {
        Point a = new Point(3, 5);
        Point b = new Point(3, 5);
        return a.hashCode() == b.hashCode() ? 1 : 0;
    }

    public static String toStr() {
        return new Point(3, 5).toString();
    }
}
